def solve_n_queens(n):
    # Simple backtracking solver
    def is_safe(board, row, col):
        # Check column
        for i in range(row):
            if board[i] == col:
                return False
            # Check diagonals
            if abs(board[i] - col) == abs(i - row):
                return False
        return True

    def backtrack(board, row):
        if row == n:
            return board[:]
        for col in range(n):
            if is_safe(board, row, col):
                board.append(col)
                result = backtrack(board, row + 1)
                if result:
                    return result
                board.pop()
        return None

    return backtrack([], 0)

solution = solve_n_queens(11)
print(solution)

def verify(board):
    n = len(board)
    for i in range(n):
        for j in range(i+1, n):
            if board[i] == board[j]:
                return False, f"Same column at rows {i} and {j}"
            if abs(board[i] - board[j]) == abs(i - j):
                return False, f"Same diagonal at rows {i} and {j}"
    return True, "Valid"

print(verify([0, 2, 4, 6, 8, 10, 1, 3, 5, 7, 9]))
